"""The fixture corpus: one refused record per reason, and a near miss beside it.

Every fixture is base64 in this file. Not because the bytes are secret, but
because a raw TOML literal in a tracked text file is normalised on the way
into git and on the way out of it, and normalisation silently deletes the
carriage return a fixture might exist to prove. Base64 means no byte of a
fixture is ever a byte of a tracked text file, which holds whatever any
clone has configured. `.gitattributes` would also work and is a rule
somebody later widens; this one cannot be widened by accident.

Each entry carries the reason it must trigger, the near miss that must be
accepted, and a note saying what the one difference between them is. The
near miss is the mistake somebody will actually make, one step short of the
refusal, because a fixture that could not have been written correctly
proves nothing about the rule that refused it.

The bytes are a snapshot of the worked record in `docs/record-format.md`
plus one change. That is deliberate: a fixture is exact bytes, so it does
not follow the document. `test_corpus.py` compares the baseline against the
document and reddens when the two part, which is where a re-freeze is
decided rather than happening quietly.

To add one: write the record to a file and encode it with

    python3 -m base64 fixture.toml

then paste the lines in beside its reason, with the reason as a comment
above them.
"""

from __future__ import annotations

import base64
import dataclasses


@dataclasses.dataclass(frozen=True)
class Fixture:
    """One refused record, the near miss beside it, and what separates them."""

    refused: str
    refused_stem: str
    accepted: str
    accepted_stem: str
    note: str

    def refused_bytes(self) -> bytes:
        return base64.b64decode(self.refused)

    def accepted_bytes(self) -> bytes:
        return base64.b64decode(self.accepted)


